using namespace std;

long long fast_exp(long long base, long long exp, long long mod) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    long long p, k;
    cin >> p >> k;
    const long long pcon = 1000000007;
    vector<long long> inv(1000003, 0);
    inv[1] = 1;
    for (long long i = 2; i < 1000003; ++i) {
        long long a = pcon / i;
        long long b = pcon % i;
        long long c = (a * (pcon - inv[b])) % pcon;
        inv[i] = c;
    }
    long long result = 0;
    if (k == 0) {
        result = 1;
        for (long long i = 0; i < p - 1; ++i) {
            result = (result * p) % pcon;
        }
    } else {
        long long prod = 1, first_found = 0, index_jj = 0;
        for (long long i = 1; i < p; ++i) {
            prod = (prod * k) % p;
            if ((prod % p) == 1 && first_found == 0) {
                index_jj = i;
                first_found = 1;
            }
        }
        result = 1;
        long long t = (p - 1) / index_jj;
        if (k == 1) {
            result = 1;
            for (long long i = 0; i < p; ++i) {
                result = (result * p) % pcon;
            }
        } else {
            long long sum = 0;
            for (long long i = 1; i <= t; ++i) {
                long long temp = (inv[i] * (t - i + 1)) % pcon;
                temp = (temp * t) % pcon;
                temp = (temp * index_jj) % pcon;
                sum = (sum + temp) % pcon;
            }
            result = (result + sum) % pcon;
        }
    }
    cout << result;
}
